unsigned char *detach_blob(BlobInfo *blob_info) {
    if (!blob_info) {
        return NULL;
    }

    if (blob_info->debug_enabled) {
        log_event("Detaching blob data");
    }

    if (blob_info->is_mapped) {
        munmap(blob_info->data, blob_info->size);
        blob_info->is_mapped = 0;
    }

    unsigned char *detached_data = blob_info->data;
    blob_info->data = NULL;
    blob_info->size = 0;

    return detached_data;
}

unsigned char *detach_blob(BlobInfo *blob_info) {
    if (!blob_info) {
        // Debug logging can be implemented here if needed
        return NULL;
    }

    // If the blob is mapped, unmap it
    if (blob_info->is_mapped && blob_info->data) {
        munmap(blob_info->data, blob_info->size);
    }

    // Retrieve the data pointer before resetting
    unsigned char *data = blob_info->data;

    // Reset the BlobInfo structure
    blob_info->data = NULL;
    blob_info->size = 0;
    blob_info->is_mapped = 0;

    return data;
}

