unsigned char *detach_blob(BlobInfo *blob_info) {
    if (!blob_info) {
        return NULL;
    }

    unsigned char *data = blob_info->data;

    if (blob_info->is_mapped) {
        if (munmap(data, blob_info->size) == -1) {
            return NULL;
        }
    }

    blob_info->data = NULL;
    blob_info->size = 0;
    blob_info->is_mapped = 0;

    return data;
}

unsigned char *detach_blob(BlobInfo *blob_info) {
    if (!blob_info) {
        if (DEBUG_ENABLED) {
            log_event("Error: NULL blob_info passed to detach_blob.");
        }
        return NULL;
    }

    if (blob_info->is_mapped) {
        if (munmap(blob_info->data, blob_info->size) == -1) {
            if (DEBUG_ENABLED) {
                log_event("Error: Failed to unmap blob data.");
            }
            return NULL;
        }
        blob_info->is_mapped = 0;
    }

    unsigned char *data = blob_info->data;
    blob_info->data = NULL;
    blob_info->size = 0;

    return data;
}
